mapper.select:
SELECT fi.id, fi.warehouse_id, fi.warehouse_name, fi.sku_no, fi.fbm_fulfillable_qty, fi.inbound_working_qty, fi.inbound_shipped_qty, fi.inbound_receiving_qty, fi.fulfillable_qty, fi.reserved_qty, fi.researching_qty, fi.unsellable_qty, fi.update_time, fi.bill_date FROM fba_history_inventory fi WHERE ${params.sqlMap.default} and fi.is_deleted = FALSE
AND NOT EXISTS (SELECT id FROM fba_history_inventory f WHERE f.id = fi.id AND fi.fbm_fulfillable_qty = 0 AND fi.inbound_working_qty = 0 AND fi.inbound_shipped_qty = 0 AND fi.inbound_receiving_qty = 0 AND fi.fulfillable_qty = 0 AND fi.reserved_qty = 0 AND fi.researching_qty = 0 AND fi.unsellable_qty = 0)
AND fi.bill_date = #{params.billDate}
${params.permissionSql}
ORDER BY fi.create_time DESC, fi.id DESC
